window.registerCatalog("ancestries",[{"id":"gayvFCiQcGNCA7aM","slug":"jotunborn","name":"Ётунорожденный","cat":"ancestries","type":"ancestry","text":"Согласно древнейшим историям, первые ётунорожденные были прямыми творениями самых первых богов. Только что завершив основную часть создания Голариона, эти боги создали несколько групп народов, которые должны были управлять этим новым миром. Среди них были и ётунорожденные — существа, образовавшиеся из останков титанов, осмелившихся восстать против богов в самые первые дни существования. Вместо того, чтобы наделить ётунорожденных всей мощью, которой они наделили титанов, боги вдохнули в первых ётунорожденных слабую искру созидания и придали им более субтильные формы. Эти новые слуги были бы столь же способны помочь в формировании остального Голариона, но при этом были слабее и их легче было бы уничтожить, если бы они взбунтовались, как их прародители.\n\nсвязанное правило","level":0,"traits":["гигант","гуманоид","Ётунорожденный"],"tags":["giant","humanoid","jotunborn"],"rarity":"редкий","remaster":true,"source":"Боевой клич!","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":25,"boosts":{"0":{"value":["str"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["cha"]}},"items":{"sfQdI":{"img":"icons/commodities/cloth/thread-spindle-white-needle.webp","level":1,"name":"Иивларское плетение","uuid":"Compendium.pf2e.ancestryfeatures.Item.Iivlar Weaving","id":"DPPFBUk0l9KfRN8h"}},"rules":[]}},{"id":"kYsBAJ103T44agJF","slug":"automaton","name":"Автоматон","cat":"ancestries","type":"ancestry","text":"Эти разумные конструкты вмещают настоящие души и они представляют собой то, что осталось от последней попытки умирающей империи достичь величия. Автоматоны сочетают в себе технологическую изобретательность и магическую силу, создавая смешанное существо, совершенно уникальное для Голариона.\n\nсвязанное правило","level":0,"traits":["Автоматон","конструкт"],"tags":["automaton","construct"],"rarity":"редкий","remaster":true,"source":"Пушки и шестерёнки","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["str"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"Djbf5":{"img":"icons/commodities/tech/cog-brass.webp","level":1,"name":"Ядро автоматона","uuid":"Compendium.pf2e.ancestryfeatures.Item.Automaton Core","id":"RYrY7o0i6s7KW9io"},"JeU1N":{"img":"systems/pf2e/icons/features/classes/expert-overdrive.webp","level":1,"name":"Сконструированное тело","uuid":"Compendium.pf2e.ancestryfeatures.Item.Constructed Body","id":"E28a45fUC2OkXZXY"}},"rules":[{"adjustName":false,"choices":[{"label":"Средний","value":"medium"},{"label":"Маленький","value":"small"}],"flag":"size","key":"ChoiceSet","prompt":"Выберите размер существа."},{"key":"ActiveEffectLike","mode":"override","path":"flags.system.automaton.enhancements","priority":10,"value":{"greater":[],"lesser":[]}}]}},{"id":"yFoojz6q3ZjvceFw","slug":"azarketi","name":"Азаркет","cat":"ancestries","type":"ancestry","text":"Азаркеты — наследники разрушенной империи, тесно хранят свои гордые традиции, но всё ещё держатся у поверхности, чтобы взаимодействовать с остальным миром.\n\nУ водных гуманоидов Внутреннего моря мрачная и тяжелая история. Большинство называют этих водных людей жаберными людьми или иногда низшими ацлантами, хотя они обычно называют себя азаркеты, ацлантским словом, которое примерно переводится как \"народ морей\". После Землепада эти гордые люди были мутированы в водных слуг своими противниками алголлусами. Чувствуя, что они не полностью принадлежат ни своим человеческим собратьям ни морю, которое объединяет их, многие азаркеты борются за чувство идентичности и цели. Несмотря на то, что жители поверхности по-прежнему не доверяют азаркетам, они прославляют свой уникальный род и свое происхождение от почитаемой ацлантской культуры.\n\nсвязанное правило","level":0,"traits":["земноводный","Азаркет","гуманоид"],"tags":["amphibious","azarketi","humanoid"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":20,"boosts":{"0":{"value":["cha"]},"1":{"value":["con"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["wis"]}},"items":{"OQZkk":{"img":"icons/magic/water/pseudopod-swirl-blue.webp","level":1,"name":"Плыть","uuid":"Compendium.pf2e.ancestryfeatures.Item.Swim","id":"c8TGiZ48ygoSPofx"},"vHxLw":{"img":"icons/commodities/materials/slime-thick-blue.webp","level":1,"name":"Гидратация","uuid":"Compendium.pf2e.ancestryfeatures.Item.Hydration","id":"vt67b8uoNEbskcBv"}},"rules":[]}},{"id":"TQEqWqc7BYiadUdY","slug":"anadi","name":"Анади","cat":"ancestries","type":"ancestry","text":"Народ анади это замкнутые, разумные пауки, родом из джунглей южного Гарунда. Хотя они во многом действуют как прирожденные оборотни, их двойные формы на самом деле являются результатом тщательно разработанной магии.\n\nсвязанное правило","level":0,"traits":["Анади","гуманоид"],"tags":["anadi","humanoid"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["con"]}},"items":{"dzt52":{"img":"systems/pf2e/icons/unarmed-attacks/mandibles.webp","level":0,"name":"Клыки","uuid":"Compendium.pf2e.ancestryfeatures.Item.Fangs","id":"dCp517IUFJk8JvQc"}},"rules":[{"alterations":[{"mode":"add","property":"traits","value":"arcane"}],"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Change Shape"}]}},{"id":"GfLwE884NoRC7cRi","slug":"android","name":"Андроид","cat":"ancestries","type":"ancestry","text":"Являясь технологическими чудесами из другого мира, андроиды имеют синтетические тела и живые души. Благодаря их двойственной природе, они сообразительны и спокойны под давлением, но безмятежными в тишине и одиночестве.\n\nсвязанное правило","level":0,"traits":["Андроид","гуманоид"],"tags":["android","humanoid"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":["int"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["cha"]}},"items":{"XxwGm":{"img":"icons/magic/control/fear-fright-white.webp","level":1,"name":"Невоспринимающий эмоции","uuid":"Compendium.pf2e.ancestryfeatures.Item.Emotionally Unaware","id":"uSAYmU7PO2QoOWhB"},"gHuOk":{"img":"systems/pf2e/icons/features/feats/effect-repair-module.webp","level":1,"name":"Созданный","uuid":"Compendium.pf2e.ancestryfeatures.Item.Constructed","id":"mnhmhOKWLiOD0lev"}},"rules":[]}},{"id":"Cg1AMgp3zrGmimWd","slug":"athamaru","name":"Атамару","cat":"ancestries","type":"ancestry","text":"Атамару — рыбоподобные гуманоиды, образующие сплоченные подводные сообщества. В небольших поселениях они занимаются выращиванием морских водорослей, дрессируют ездовых угрей, и создают сложные произведения кораллового искусства. Взаимодействие с другими водными народами у них натянутое, поскольку атамару подвергались жестокому обращению с их стороны. Тем не менее, они не теряют интереса к потенциальным контактам и новым перспективам.\n\nсвязанное правило","level":0,"traits":["земноводный","Атамару","гуманоид"],"tags":["amphibious","athamaru","humanoid"],"rarity":"необычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":20,"boosts":{"0":{"value":["str"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["int"]}},"items":{},"rules":[]}},{"id":"cLtOGIkuSSa4UDHY","slug":"vanara","name":"Ванар","cat":"ancestries","type":"ancestry","text":"Ванары — любознательные и озорные обезьяноподобные гуманоиды с короткой мягкой шерстью, выразительными глазами и длинными, цепкими хвостами. Их ноги, похожие на руки, и проворное телосложение хорошо помогают им в джунглях, где и живет большинство ванаров.\n\nсвязанное правило","level":0,"traits":["гуманоид","Ванар"],"tags":["humanoid","vanara"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"zLIjA":{"img":"icons/commodities/biological/tail-rodent-striped-red.webp","level":1,"name":"Цепкий хвост","uuid":"Compendium.pf2e.ancestryfeatures.Item.Prehensile Tail","id":"PtvzTm2gjdCKao4I"}},"rules":[]}},{"id":"8FpI46oVxYVku04u","slug":"wayang","name":"Ваянг","cat":"ancestries","type":"ancestry","text":"Ваянги — диаспора, пришедшая из Незримого Мира , где они жили и работали вместе со своими союзниками д'зириаками. Оба народа разделяли склонность к художественному самовыражению и духовному самоанализу, вдохновляя друг друга на восприятие цвета, формы и функций; они также поддерживали друг друга в защите от разбушевавшихся драконов, они и нежити. Эта идиллия разрушилась из-за божественного вмешательства, некоторые говорят, что когда Абадар приговорил Зон-Кутона к изгнанию в Незримый Мир, божественное присутствие Владыки Полуночи исказило план, превратив его в кошмарный домен, в то время как другие рассказы приписывают этой катастрофе дьявольские источники.\n\nсвязанное правило","level":0,"traits":["гуманоид","тень","Ваянг"],"tags":["humanoid","shadow","wayang"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["con"]}},"items":{},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"flags.system.colorDarkvision","value":true}]}},{"id":"u1VJEXsVlmh3Fyx0","slug":"vishkanya","name":"Вишканья","cat":"ancestries","type":"ancestry","text":"Вишканьи — гуманоиды относящиеся к змеям, в крови и слюне которых содержится сильный яд. Во многом непонятые из-за старых историй об их токсичности и природном изяществе, вишканьи стараются развиться в нечто большее, чем то, как их изображают истории.\n\nсвязанное правило","level":0,"traits":["гуманоид","Вишканья"],"tags":["humanoid","vishkanya"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"0wY9n":{"img":"icons/skills/melee/blade-tip-energy-green.webp","level":0,"name":"Врожденный яд","uuid":"Compendium.pf2e.ancestryfeatures.Item.Innate Venom","id":"IXyXCMBldrU5G60e"}},"rules":[]}},{"id":"CYlfsYLJcBOgqKtD","slug":"gnome","name":"Гном","cat":"ancestries","type":"ancestry","text":"Давным-давно, ранние предки гномов переселились из Первого Мира, царства фей. Хоть и неясно, почему первые гномы забрели в Голарион, эта родословная проявляется в современных гномах в виде причудливых умозаключений, неординарности, навязчивых склонностях и том, что некоторые считают наивностью. Эти качества также отражаются в их физических чертах, таких как тонкие конечности, ярко окрашенные волосы и детские и чрезвычайно выразительные черты лица, которые еще больше отражают их потустороннее происхождение.\n\nсвязанное правило","level":0,"traits":["Гном","гуманоид"],"tags":["gnome","humanoid"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["cha"]},"1":{"value":["con"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["str"]}},"items":{},"rules":[]}},{"id":"sQfjTMDaZbT9DThq","slug":"goblin","name":"Гоблин","cat":"ancestries","type":"ancestry","text":"Гоблинов не интересуют запутанные истории, за которые цепляются другие народы. Этот маленький народ живет настоящим, и они предпочитают небылицы фактам. Войны, произошедшие несколько десятилетий назад, с таким же успехом могли быть в далеком прошлом. Непонятые другими людьми, гоблины счастливы такими, какие они есть. Добродетели гоблинов состоят в том, чтобы быть участливым, творческим и честным. Они стремятся вести полноценную жизнь, а не беспокоиться о том, чем закончатся их путешествия. Рассказывать истории, а не придираться к фактам. Быть маленьким, но мечтать о большом.\n\nсвязанное правило","level":0,"traits":["Гоблин","гуманоид"],"tags":["goblin","humanoid"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["cha"]},"1":{"value":["dex"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["wis"]}},"items":{},"rules":[]}},{"id":"c4secsSNG2AO7I5i","slug":"goloma","name":"Голома","cat":"ancestries","type":"ancestry","text":"Голомы боятся большинства других людей и сознательно используют свою необычную биологию, чтобы отпугивать тех, кого они считают опасными хищниками. Редко замечаемые и плохо понятые, образ многоглазых и деревянноликих голом внушает ужас большинству тех, с кем они встречаются.\n\nсвязанное правило","level":0,"traits":["Голома","гуманоид"],"tags":["goloma","humanoid"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":30,"boosts":{"0":{"value":["wis"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"LXQc0":{"img":"systems/pf2e/icons/spells/prying-eye.webp","level":1,"name":"Глаза на затылке","uuid":"Compendium.pf2e.ancestryfeatures.Item.Eyes in Back","id":"AUlPRySCqE6o6LHH"}},"rules":[]}},{"id":"tSurOqRcfumadTfr","slug":"ghoran","name":"Горан","cat":"ancestries","type":"ancestry","text":"Эти разумные люди-растения, созданные давно умершим друидом, обладают своего рода бессмертием благодаря своим семенам — до тех пор, пока они не будут уничтожены внешними событиями, отличными от разрушительного действия времени.\n\nсвязанное правило","level":0,"traits":["Горан","гуманоид","растение"],"tags":["ghoran","humanoid","plant"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"Jpors":{"img":"icons/magic/nature/root-vine-beanstolk-green.webp","level":0,"name":"Фотосинтез","uuid":"Compendium.pf2e.ancestryfeatures.Item.Photosynthesis","id":"N0zhJ0whkDJPlftl"}},"rules":[]}},{"id":"BYj5ZvlXZdpaEgA6","slug":"dwarf","name":"Дварф","cat":"ancestries","type":"ancestry","text":"Дварфы имеют заслуженную репутацию стойкого и сурового народа, укрывшегося в цитаделях и городах, высеченных в скалах. В то время как некоторые видят в них хмурых и лишенных чувства юмора ремесленников, создающих вещи из камня и металла, дварфы и те, кто провел время среди них, понимают их необузданное рвение к своей работе и заботе о качестве, нежели чем о количестве. Чужаку они могут показаться недоверчивыми и обособленными, но для своих друзей и семьи они сердечные и заботливые, их залы наполнены звуками смеха и молотов, бьющих по наковальням.\n\nсвязанное правило","level":0,"traits":["Дварф","гуманоид"],"tags":["dwarf","humanoid"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":20,"boosts":{"0":{"value":["con"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["cha"]}},"items":{"5vjeq":{"img":"systems/pf2e/icons/equipment/weapons/clan-dagger.webp","level":0,"name":"Клановый кинжал","uuid":"Compendium.pf2e.ancestryfeatures.Item.Clan Dagger","id":"Eyuqu6eIaoGCjnMv"}},"rules":[]}},{"id":"FXlXmNBFiiz9oasi","slug":"fleshwarp","name":"Деформированный","cat":"ancestries","type":"ancestry","text":"Флэшворпы — люди, чьи формы были созданы или радикально преобразованы с помощью магии, алхимии или неестественных энергий. Их неортодоксальная внешность может мешать им найти себе место в мире.\n\nсвязанное правило","level":0,"traits":["аберрация","гуманоид"],"tags":["aberration","humanoid"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"31xm9":{"img":"systems/pf2e/icons/default-icons/feat.svg","level":1,"name":"Необычная анатомия","uuid":"Compendium.pf2e.ancestryfeatures.Item.Unusual Anatomy","id":"mEDTJi7d1bTEiwUD"}},"rules":[{"adjustName":false,"choices":[{"label":"Маленький","value":"sm"},{"label":"Средний","value":"med"}],"flag":"fleshwarpSize","key":"ChoiceSet","prompt":"Выберите размер существа."}]}},{"id":"B5Ewz31nJBOzHSMg","slug":"dragonet","name":"Дракончик","cat":"ancestries","type":"ancestry","text":"Дракончики — миниатюрные драконы, у которых есть крылья, зубы, похожие на кинжалы, и магическое дыхание. Они могут быть невероятно независимыми и гордыми, иногда покровительственными или жадными, и они наслаждаются прекрасными вещами в жизни.\n\nсвязанное правило","level":0,"traits":["дракон"],"tags":["dragon"],"rarity":"редкий","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":20,"boosts":{"0":{"value":["dex"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["con"]}},"items":{"BDkKf":{"img":"icons/creatures/abilities/mouth-teeth-rows-red.webp","level":1,"name":"Большие острые зубы","uuid":"Compendium.pf2e.ancestryfeatures.Item.Big Sharp Teeth","id":"PCLnnWPbiiSzrxEo"},"lxyWw":{"img":"icons/creatures/abilities/wing-batlike-white-blue.webp","level":1,"name":"Крылья (Дракончик)","uuid":"Compendium.pf2e.ancestryfeatures.Item.Wings (Dragonet)","id":"RjWv5oPKZtNQgEiK"}},"rules":[]}},{"id":"dw2K1AJR9mQ25nDP","slug":"kashrishi","name":"Кашриши","cat":"ancestries","type":"ancestry","text":"Кашриши живут в отдаленных регионах мира. У этих спокойных существ крепкое, прочное телосложение и характерные кристаллические рога. Их врожденные экстрасенсорные способности делают их прирожденными эмпатами, но также иногда обременяют их непрекращающимися мыслями о своих соседях.\n\nсвязанное правило","level":0,"traits":["гуманоид","Кашриши"],"tags":["humanoid","kashrishi"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"iaCUe":{"img":"systems/pf2e/icons/spells/enthrall.webp","level":0,"name":"Чувство эмпатии","uuid":"Compendium.pf2e.ancestryfeatures.Item.Empathic Sense","id":"QyBfftocP1i43Qrp"},"wceqv":{"img":"systems/pf2e/icons/spells/searing-light.webp","level":0,"name":"Светящийся рог","uuid":"Compendium.pf2e.ancestryfeatures.Item.Glowing Horn","id":"8sxtjVsk9HBY5yAv"}},"rules":[]}},{"id":"pJkQlFTvpQ5GjZ5e","slug":"centaur","name":"Кентавр","cat":"ancestries","type":"ancestry","text":"Кентавры — гордые кочевники, которые далеко путешествуют по своим исконным территориям, защищая свои земли от эксплуатации и вторжения. Они — прирожденные выживальщики, крепко связывающие себя узами семьи и общины и стойко переносящие опасность. Многие из них — искусные охотники, следопыты и воины, сражающиеся с помощью лука, стали и копыт. Храбрые и упрямые, они готовы бросить вызов даже самым свирепым врагам и самым большим армиям, чтобы защитить свои дома, родственников и свои владения.\n\nсвязанное правило","level":0,"traits":["чудовище","Кентавр","гуманоид"],"tags":["beast","centaur","humanoid"],"rarity":"необычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":30,"boosts":{"0":{"value":["str"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["cha"]}},"items":{"TaKbB":{"img":"icons/environment/people/cavalry.webp","level":1,"name":"Оседлать","uuid":"Compendium.pf2e.ancestryfeatures.Item.Mount","id":"PM5jvValFkbFH3TV"},"fRFKM":{"img":"icons/skills/movement/arrows-up-trio-red.webp","level":1,"name":"Мощный","uuid":"Compendium.pf2e.ancestryfeatures.Item.Robust","id":"S5XriNcxiVvqZEu0"}},"rules":[]}},{"id":"4BL5wf1VF9feC2rY","slug":"kitsune","name":"Кицунэ","cat":"ancestries","type":"ancestry","text":"Кицунэ — харизматичный и остроумный народ, имеющий связь с духовным, что дает им много магических умений, и главным образом силу превращаться в другие формы. Независимо от того, проходят ли они незамеченными среди других народов или высоко держат хвосты, кицунэ умело наблюдают за окружающими их обществами.\n\nсвязанное правило","level":0,"traits":["гуманоид","Кицунэ"],"tags":["humanoid","kitsune"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["cha"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"lzwB0":{"img":"icons/creatures/mammals/humanoid-fox-cat-archer.webp","level":1,"name":"Изменение формы","uuid":"Compendium.pf2e.ancestryfeatures.Item.Change Shape","id":"34E7k2YRcsOU5uyl"}},"rules":[]}},{"id":"7oQxL6wgsokD3QXG","slug":"kobold","name":"Кобольд","cat":"ancestries","type":"ancestry","text":"Каждый кобольд инстинктивно понимает важность власти, и многие склонны почитать тех, кто ею обладает, будь то могущественные драконы, жестокие бесы, властные феи или даже древние артефакты. Кобольды стремятся к таким союзам не только из чувства прагматизма — ведь кто посмеет задирать кобольда, служащего древнему дракону, — но и потому, что яйца кобольдов, высиживаемые вблизи таких мест силы, приобретают физические черты (а иногда и способности), схожие с теми, которыми обладает покровитель логова. Сами по себе кобольды — изобретательные ремесленники и преданные союзники, но чужаки, кто вторгается на их территорию, узнают что они вдохновенные стрелки. Однако эти рептилоидные оппортунисты счастливы сотрудничать с другими гуманоидами, когда это им выгодно, сочетая осторожность и хитрость, чтобы заработать состояния в большом мире.\n\nсвязанное правило","level":0,"traits":["гуманоид","Кобольд"],"tags":["humanoid","kobold"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["cha"]},"1":{"value":["dex"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["con"]}},"items":{},"rules":[]}},{"id":"tZn4qIHCUA6wCdnI","slug":"conrasu","name":"Конрас","cat":"ancestries","type":"ancestry","text":"Конрасы — это осколки космической силы, получившей сознание, которые создают замысловатые экзоскелеты для взаимодействия с миром смертных. Являясь неотъемлемой частью основополагающих процессов Вселенной и будучи странно обособленными, конрасы обращаются к эонам, чтобы понять свое существование.\n\nсвязанное правило","level":0,"traits":["эон","Конрас","растение"],"tags":["aeon","conrasu","plant"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["cha"]}},"items":{"SECEF":{"img":"icons/magic/light/explosion-beam-impact-silhouette.webp","level":1,"name":"Исцеление солнечным светом","uuid":"Compendium.pf2e.ancestryfeatures.Item.Sunlight Healing","id":"BgHrucbZ9TH92RDv"}},"rules":[]}},{"id":"972EkpJOPv9KkQIW","slug":"catfolk","name":"Коточеловек","cat":"ancestries","type":"ancestry","text":"Любопытные и общительные странники, котолюди сочетают в себе черты животных из семейства кошачьих и гуманоидов как по внешнему виду, так и по темпераменту. Им нравится узнавать новое, собирать новые истории и безделушки, а также заботиться о том, чтобы их близкие были в безопасности и счастливы. Котолюди считают себя избранными хранителями природных мест в мире и часто безрассудно храбры, даже перед лицом превосходящей опасности. Они считают, что в этой борьбе им помогают сильные общины, богатый опыт и постоянное самосовершенствование.\n\nсвязанное правило","level":0,"traits":["Коточеловек","гуманоид"],"tags":["catfolk","humanoid"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["cha"]},"1":{"value":["dex"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["wis"]}},"items":{"iyksy":{"img":"systems/pf2e/icons/features/ancestry/land-on-your-feet.webp","level":"1","name":"Приземление на лапы","uuid":"Compendium.pf2e.ancestryfeatures.Item.Land on Your Feet","id":"sL1hHxrHdMNIZVAd"}},"rules":[]}},{"id":"P6PcVnCkh4XMdefw","slug":"ratfolk","name":"Крысолюд","cat":"ancestries","type":"ancestry","text":"Исоки — это существа, которых большинство гуманоидов, живущих на поверхности, называют \"крысолюды\". Это общинный народ, предпочитающий тесные условия, когда в одном доме живет до 100 представителей. Если им не удается найти дом в городе, крысолюды могут поселиться в пещерах и пещерных комплексах, так как те служат отличным хранилищем для многочисленных и разнообразных товаров, которые они привозят из торговых экспедиций.\n\nсвязанное правило","level":0,"traits":["гуманоид","Крысолюд"],"tags":["humanoid","ratfolk"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":["int"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["str"]}},"items":{"jkllM":{"img":"icons/commodities/bones/skull-lizard-tan.webp","level":1,"name":"Острые зубы","uuid":"Compendium.pf2e.ancestryfeatures.Item.Sharp Teeth","id":"sW4ObB8wyLPPYvGj"}},"rules":[]}},{"id":"6F2fSFC1Eo1JdpY4","slug":"poppet","name":"Кукла","cat":"ancestries","type":"ancestry","text":"Куклы — это маленькие, простые конструкты, которые обычно помогают своим хозяевам выполнять простые задачи. Порой они обретают разум, независимость и искру жизни. Поднявшись над простыми помощниками или игрушками, эти куклы могут самостоятельно определять свои судьбы.\n\nсвязанное правило","level":0,"traits":["конструкт","гуманоид"],"tags":["construct","humanoid"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["dex"]}},"items":{"M1KcQ":{"img":"icons/magic/fire/flame-burning-skeleton-explosion.webp","level":1,"name":"Легковоспламеняющийся","uuid":"Compendium.pf2e.ancestryfeatures.Item.Flammable","id":"qKh6MxgE0cwde6mC"},"SoFFU":{"img":"icons/magic/control/voodoo-doll-pain-damage-yellow.webp","level":1,"name":"Созданный (Кукла)","uuid":"Compendium.pf2e.ancestryfeatures.Item.Constructed (Poppet)","id":"BHPDeqQHqi7ukCUW"}},"rules":[]}},{"id":"vxbQ1Yw4qwgjTzqo","slug":"kholo","name":"Кхоло","cat":"ancestries","type":"ancestry","text":"У кхоло сложилась дурная репутация жестоких рейдеров и демонопоклонников. Многие считают, что кхоло — ведьмы, каннибалы и ещё хуже. Истина гораздо сложнее. Кхоло — исключительно практичные и прагматичные охотники и рейдеры. Для них честь — это всего лишь слово, обозначающее бессмысленный риск. Любая потеря кхоло сказывается не только на нём самом, но и на его товарищах и сородичах. Тратить время на что-либо, кроме победы, будь то милосердие или жестокость, считается почти безнравственным. Кхоло — мастера засад, тактических уловок и психологической войны. Столь же непонятна практика кхоло поклонения предкам и эндоканнибализма. Кхоло съедают своих мертвецов в знак почтения, устраивая грандиозный пир и превращая кости в предметы искусства или оружие. Кхоло оказывают такую честь и уважаемым врагам, надеясь привнести в клан хитрость или силу своего противника.\n\nсвязанное правило","level":0,"traits":["гуманоид","Кхоло"],"tags":["humanoid","kholo"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["str"]},"1":{"value":["int"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["wis"]}},"items":{"Awa7a":{"img":"icons/creatures/abilities/mouth-teeth-long-red.webp","level":0,"name":"Укус","uuid":"Compendium.pf2e.ancestryfeatures.Item.Bite","id":"jatezR4bENwhC6GL"}},"rules":[]}},{"id":"cdhgByGG1WtuaK73","slug":"leshy","name":"Леший","cat":"ancestries","type":"ancestry","text":"Хранители и эмиссары окружающей среды, лешие — бессмертные духи природы, которым временно дарована физическая форма.\n\nсвязанное правило","level":0,"traits":["Леший","растение"],"tags":["leshy","plant"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["int"]}},"items":{"32oz7":{"img":"icons/magic/nature/root-vine-beanstolk-green.webp","level":"1","name":"Растительное питание","uuid":"Compendium.pf2e.ancestryfeatures.Item.Plant Nourishment","id":"Sm3tKetM6kddTio3"}},"rules":[]}},{"id":"HWEgF7Gmoq55VhTL","slug":"lizardfolk","name":"Людоящер","cat":"ancestries","type":"ancestry","text":"Людоящеры — непревзойденные выживальщики, наследники империй даже эльфами считающиеся древними.\n\nсвязанное правило","level":0,"traits":["гуманоид","Людоящер"],"tags":["humanoid","lizardfolk"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["str"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["int"]}},"items":{"ry9ai":{"img":"systems/pf2e/icons/features/ancestry//aquatic-adaptation.webp","level":"1","name":"Водная адаптация","uuid":"Compendium.pf2e.ancestryfeatures.Item.Aquatic Adaptation","id":"AzGJN1wwLFaLJIeo"},"xkzsg":{"img":"systems/pf2e/icons/features/ancestry/claws.webp","level":"1","name":"Когти","uuid":"Compendium.pf2e.ancestryfeatures.Item.Claws","id":"NfkxFWUeG6g41e8w"}},"rules":[]}},{"id":"FUqZRllwn6kmFA8K","slug":"merfolk","name":"Мерфолк","cat":"ancestries","type":"ancestry","text":"Мерфолки живут во всех океанах Голариона, бесконечные в своем разнообразии и внушающие благоговение своим величием. Они не без основания считают себя правителями моря. Среди тропических рифов Лихорадочного моря мерфолки строят храмы и дворцы из ярких кораллов. Под льдинами Сияющего моря мерфолки охотятся на тюленей и китов, объединяясь в небольшие обособленные кланы. В океане Эмбарал мерфолки населяют великий торговый город Алохмаб , построенный в раковине титанической улитки, которая ползет по дну океана.\n\nсвязанное правило","level":0,"traits":["земноводный","гуманоид","Мерфолк"],"tags":["amphibious","humanoid","merfolk"],"rarity":"необычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":5,"boosts":{"0":{"value":["dex"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["con"]}},"items":{"1ZhYb":{"img":"icons/magic/water/water-hand.webp","level":0,"name":"Гидратация (Мерфолк)","uuid":"Compendium.pf2e.ancestryfeatures.Item.Hydration (Merfolk)","id":"DWNRIgt3f92fSTBM"},"T9WbI":{"img":"icons/magic/water/pseudopod-swirl-blue.webp","level":0,"name":"Водная грация","uuid":"Compendium.pf2e.ancestryfeatures.Item.Aquatic Grace","id":"d5TYEND07kwWRBIq"}},"rules":[]}},{"id":"3wQ49DoWFYQgVsq6","slug":"minotaur","name":"Минотавр","cat":"ancestries","type":"ancestry","text":"Минотавры — мастера каменного зодчества, они обитают в сложных коридорах, как естественных, так и искусственных. Любознательные и стойкие, эти быкообразные гуманоиды всю жизнь совершенствуются в своем деле, которое иногда заводит их далеко от анклавов, где они были воспитаны. Минотавры родом с архипелага Иблидос , но распространились далеко по Голариону, образуя сплочённые сообщества, часто вблизи гор или под поверхностью земли. Хотя иногда их принимают за простых грубиянов, среди минотавров есть и ученые, и воины. Те, кто не придаёт значения их внешнему виду, обнаруживают в них склонность к строительству и навигации, а также к творческому решению проблем.\n\nсвязанное правило","level":0,"traits":["чудовище","гуманоид","Минотавр"],"tags":["beast","humanoid","minotaur"],"rarity":"необычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":25,"boosts":{"0":{"value":["str"]},"1":{"value":["con"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["cha"]}},"items":{"MZeAa":{"img":"icons/creatures/abilities/bull-head-horns-glowing.webp","level":1,"name":"Особенность класса","uuid":"Compendium.pf2e.ancestryfeatures.Item.Horns (Minotaur)","id":"hUpYTsbLcBg4UcVp"}},"rules":[]}},{"id":"J7T7bDLaQGoY1sMF","slug":"nagaji","name":"Нагаджи","cat":"ancestries","type":"ancestry","text":"Обладая гуманоидными телами и змеевидными головами, нагаджи являются глашатаями, спутниками и слугами могущественных наг. Они с глубоким почтением относятся к святым местам и духовным истинам, что многие другие считают столь же пугающим, как и внешность нагаджи.\n\nсвязанное правило","level":0,"traits":["гуманоид","Нагаджи"],"tags":["humanoid","nagaji"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":25,"boosts":{"0":{"value":["str"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"O6GUQ":{"img":"icons/skills/wounds/bone-broken-tooth-fang-red.webp","level":0,"name":"Клыки (Нагаджи)","uuid":"Compendium.pf2e.ancestryfeatures.Item.Fangs (Nagaji)","id":"jS8GamSTl8yMLL4F"}},"rules":[]}},{"id":"lSGWXjcbOa6O5fTx","slug":"orc","name":"Орк","cat":"ancestries","type":"ancestry","text":"Орки закаляются в огне насилия и конфликтов, часто с самого момента своего рождения. Живя жизнью, которая часто жестоко обрывается, орки упиваются тем, что испытывают свои силы против достойных врагов, бросая вызов высокопоставленному члену своего сообщества за господство или совершая набег на соседнее поселение. Многие орки ищут славы, как только они начинают ходить и могут носить меч или дубину, укрощая диких зверей или охотясь на смертельных монстров.\n\nсвязанное правило","level":0,"traits":["гуманоид","Орк"],"tags":["humanoid","orc"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":25,"boosts":{"0":{"value":["cha","con","dex","int","str","wis"]},"1":{"value":["cha","con","dex","int","str","wis"]},"2":{"value":[]}},"flaws":{"0":{"value":[]}},"items":{},"rules":[]}},{"id":"GgZAHbrjnzWOZy2v","slug":"halfling","name":"Полурослик","cat":"ancestries","type":"ancestry","text":"Не претендуя на своё собственное место, полурослики имеют лишь несколько поселений крупнее деревень. Вместо этого они часто живут среди людей в стенах крупных городов, создавая небольшие сообщества рядом с более высокими народами. Многие полурослики ведут совершенно полноценную жизнь в тени своих более крупных соседей, в то время как другие предпочитают кочевать, путешествуя по миру и пользуясь возможностями по мере появления и попадая в приключения.\n\nсвязанное правило","level":0,"traits":["Полурослик","гуманоид"],"tags":["halfling","humanoid"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["str"]}},"items":{"3084v":{"img":"systems/pf2e/icons/features/ancestry/keen-eyes.webp","level":"0","name":"Зоркие глаза","uuid":"Compendium.pf2e.ancestryfeatures.Item.Keen Eyes","id":"y1EmCv2cEb5hXBwx"}},"rules":[]}},{"id":"GFOgV3MzWkYwJoJW","slug":"awakened-animal","name":"Пробуждённое животное","cat":"ancestries","type":"ancestry","text":"Когда-то вы наслаждались простыми и безграничными удовольствиями природы с невинным, незамутнённым разумом. Вы жили мгновениями, не задаваясь вопросом, что будет дальше, и не размышляя о последствиях того, что произошло раньше. Вы были едины с дикой природой. Затем произошло событие, которое изменило всё. Вы выпили из светящегося озера, кто-то устроил магический розыгрыш, друид пытался возвысить ваш разум. Вас выдернули из настоящего мгновения дикой природы в страну мыслей.\n\nсвязанное правило","level":0,"traits":["Пробуждённое животное","чудовище"],"tags":["awakened-animal","beast"],"rarity":"редкий","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":5,"boosts":{"0":{"value":["con"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["int"]}},"items":{"9KYmO":{"img":"icons/creatures/mammals/humanoid-wolf-dog-blue.webp","level":1,"name":"Пробуждённый разум","uuid":"Compendium.pf2e.ancestryfeatures.Item.Awakened Mind","id":"0qHN69NF7JBWKO8v"},"TQ7e5":{"img":"icons/magic/nature/wolf-paw-glow-green.webp","level":1,"name":"Пробуждённая форма","uuid":"Compendium.pf2e.ancestryfeatures.Item.Awakened Form","id":"ItQDbIiqpb50Zbtm"}},"rules":[{"adjustName":false,"choices":[{"label":"Большой","value":{"hitPoints":10,"size":"large"}},{"label":"Средний","value":{"hitPoints":8,"size":"medium"}},{"label":"Маленький","value":{"hitPoints":6,"size":"small"}},{"label":"Крошечный","value":{"hitPoints":6,"size":"tiny"}}],"flag":"choice","key":"ChoiceSet","prompt":"Выберите размер существа."},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.attributes.ancestryhp","priority":51,"value":"{item|flags.system.rulesSelections.choice.hitPoints}"}]}},{"id":"l7vjMIbPAUvEIosU","slug":"samsaran","name":"Самсар","cat":"ancestries","type":"ancestry","text":"Если верить легендам, самсары произошли от группы ученых из Чжи Ха, что отправились в горы на поиски лекарства от болезни, что подирала их деревню. После недель тяжких испытаний, им удалось найти источник воды, наполненной чистейшей магической эссенцией жизни. Эта вода позволила ученым выжить и исцелила жителей деревни. Получив ещё один шанс на жизнь, все испившие этой воды посвятили остаток жизни обучению и постижению мира во всем его многообразии. После смерти, их приверженность, вкупе с магической эссенцией, что текла теперь по их венам, превратила их в первых самсаров.\n\nсвязанное правило","level":0,"traits":["гуманоид","Самсар"],"tags":["humanoid","samsaran"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["cha"]}},"items":{"Be6lQ":{"img":"icons/magic/perception/third-eye-blue-red.webp","level":1,"name":"Криптомнезия","uuid":"Compendium.pf2e.ancestryfeatures.Item.Cryptomnesia","id":"QLSvmOid6gAdzBYi"},"xYhuY":{"img":"icons/magic/symbols/ring-circle-smoke-blue.webp","level":1,"name":"Душа странника","uuid":"Compendium.pf2e.ancestryfeatures.Item.Wanderer's Soul","id":"D6AjSg0JOYtn7Coa"}},"rules":[]}},{"id":"7mpMGhVoaPANJnZ8","slug":"sarangay","name":"Сарангай","cat":"ancestries","type":"ancestry","text":"Сарангаи это гуманоиды с головами азиатского буйвола, издавна живущие в глубине лесов Тянь Ся. Многие авантюристы поначалу считали их чудовищами, но сарангаи — не что иное, как процветающее общество, ценящая свою общину и душу превыше всего. Их культура построена на сильном желании защитить свою общину и избранного лидера. Считается, что их рога — это полумесяц, а их высокий рост произошел от того, что их предки вытянулись так далеко вверх, чтобы дотянуться до Отца Луны, в то время как их Мать Земля держала их рядом со своим лоном. Они почитают великого Отца Луну, своего Первого Предка и стремятся защищать и возвеличивать природу превыше всего, поскольку понимают, что являются её частью.\n\nсвязанное правило","level":0,"traits":["гуманоид","Сарангай"],"tags":["humanoid","sarangay"],"rarity":"редкий","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["str"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["wis"]}},"items":{"PIA9y":{"img":"icons/commodities/gems/gem-rough-cushion-red.webp","level":1,"name":"Головной самоцвет","uuid":"Compendium.pf2e.ancestryfeatures.Item.Head Gem","id":"HYefFkddD9lOhFM8"},"bPf5G":{"img":"icons/creatures/abilities/bull-head-horns-glowing.webp","level":1,"name":"Рога (Сарангай)","uuid":"Compendium.pf2e.ancestryfeatures.Item.Horns (Sarangay)","id":"LhgVj9GhPsXGfwAM"}},"rules":[]}},{"id":"58rL5sg2y4arW1i5","slug":"skeleton","name":"Скелет","cat":"ancestries","type":"ancestry","text":"Скелеты считаются одним из низших видов нежити. Как правило, это неразумные существа, лишенные многих возможностей, делающих другую нежить серьезной угрозой. Однако ожившие кости драконов, гигантов и других огромных чудовищ становятся опасными противниками. Могущественные живые существа могут сохранить часть своей силы и интеллекта, вернувшись в виде скелета. Некоторые некроманты превращают своих самых сильных врагов в скелетных слуг-нежить, если, конечно, смогут удержать над ними контроль.\n\nсвязанное правило","level":0,"traits":["Скелет","нежить"],"tags":["skeleton","undead"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["int"]}},"items":{"pADW6":{"img":"icons/magic/death/skull-humanoid-white-blue.webp","level":0,"name":"Основные преимущества нежити","uuid":"Compendium.pf2e.ancestryfeatures.Item.Basic Undead Benefits","id":"SAbzItAI4uwbdnQk"}},"rules":[]}},{"id":"TRqoeYfGAFjQbviF","slug":"sprite","name":"Спрайт","cat":"ancestries","type":"ancestry","text":"Спрайты — крохотные, причудливые и жизнерадостные существа из царства фей, известного как Первый мир. Они любят устраивать розыгрыши, исследовать новое и охватывать все, что связано с магией.\n\nсвязанное правило","level":0,"traits":["фея","Спрайт"],"tags":["fey","sprite"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":20,"boosts":{"0":{"value":["dex"]},"1":{"value":["int"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["str"]}},"items":{"55xmg":{"img":"icons/creatures/magical/fae-fairy-winged-glowing-green.webp","level":1,"name":"Магические удары","uuid":"Compendium.pf2e.ancestryfeatures.Item.Magical Strikes","id":"TRw4oBZBFZG96jKO"}},"rules":[]}},{"id":"GXcC6oVa5quzgNHD","slug":"strix","name":"Стрикс","cat":"ancestries","type":"ancestry","text":"Известные на своем языке как итарии, стриксы — птичьи гуманоиды живущие уединенно, преданные своей родине и своим племенам. Они защищают свои драгоценные сообщества широким размахом крыльев и острыми когтями.\n\nсвязанное правило","level":0,"traits":["гуманоид","Стрикс"],"tags":["humanoid","strix"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"uECVZ":{"img":"systems/pf2e/icons/spells/unfettered-pack.webp","level":1,"name":"Крылья","uuid":"Compendium.pf2e.ancestryfeatures.Item.Wings","id":"oCIO7UJqbpTkI62l"}},"rules":[]}},{"id":"ALOmLePjbc37ca3Y","slug":"surki","name":"Суркай","cat":"ancestries","type":"ancestry","text":"Суркаи — насекомоподобные существа, которые питаются скрытой магией окружающего мира. Будучи подземным народом, обитающим в Тёмноземье, суркаи редко появляются на поверхности, и между документированными встречами с ними большие перерывы. Это связано с жизненным циклом суркаев — за длительными периодами покоя следуют так называемые \"раскопки поколения\" (\"\"), когда они мигрируют на большие расстояния в ответ на происходящее под землёй. Исцеление Мировой Язвы положило начало одному из крупнейших подобных раскопок за всю их историю: суркаи поднялись в пещеры и ходы Шрама Саркориса и впервые за много лет вышли на поверхность. С момента их появления в укромных уголках Саркориса появилось несколько небольших поселений суркаев, ненасытно изучающих дикую природу, магию и других обитателей здешних мест, исследуя чужеродную им поверхность.\n\nсвязанное правило","level":0,"traits":["гуманоид","Суркай"],"tags":["humanoid","surki"],"rarity":"редкий","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"Ve2AG":{"img":"icons/magic/symbols/rune-sigil-green-purple.webp","level":1,"name":"Магофаг","uuid":"Compendium.pf2e.ancestryfeatures.Item.Magiphage","id":"oQ5478uONrGAWRgF"}},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"flags.system.surki.evolutions","priority":10,"value":[]}]}},{"id":"pILFsoGsUQkVF5dZ","slug":"tanuki","name":"Тануки","cat":"ancestries","type":"ancestry","text":"Тянь Ся изобилуют магически одаренными родословными: тэнгу, кицунэ, якшами и яогаями, чьи способности приносят им высокое уважение и использующие свой дар в ответственных целях. Тануки к таким родословным не относятся. Напротив, эти похожие на енотовидных собак гуманоиды используют свои способности к иллюзиям и превращениям так, как должны использовать все смертные: для развлечения! Тануки обожают розыгрыши и шутки, особенно те, которые позволяют им сбить спесь с высокопоставленных лиц и показать им, что такое жизнь для остальных. Там, где другие народы гордятся своей богатой историей, благородными традициями или сложными церемониями, тануки гордятся своей простотой и пренебрежением к многочисленным правилам мира. Хотя некоторые могут утверждать, что такой взгляд на вещи низводит тануки до уровня неотесанных обывателей, тануки считают, что это делает их более культурными: ведь, чтобы нарушить правило, нужно его знать, а чтобы его нарушить, нужно понять норму.\n\nсвязанное правило","level":0,"traits":["гуманоид","Тануки"],"tags":["humanoid","tanuki"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":10,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["wis"]}},"items":{},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Change Shape"}]}},{"id":"hXM5jXezIki1cMI2","slug":"tripkee","name":"Трипки","cat":"ancestries","type":"ancestry","text":"Трипки — застенчивый и осторожный народ, который обычно старается не втягиваться в дела других. Несмотря на свою осторожное мировоззрение и небольшой рост, когда того требует ситуация, отважные трипки часто предпринимают смелые и благородные действия.\n\nсвязанное правило","level":0,"traits":["гуманоид","Трипки"],"tags":["humanoid","tripkee"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":["wis"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["str"]}},"items":{"3lJFy":{"img":"icons/creatures/amphibians/treefrog-leaf-green.webp","level":1,"name":"Прирождённый скалолаз","uuid":"Compendium.pf2e.ancestryfeatures.Item.Natural Climber","id":"gZvgt5n5OYO3av2V"}},"rules":[]}},{"id":"18xDKYPDBLEv2myX","slug":"tengu","name":"Тэнгу","cat":"ancestries","type":"ancestry","text":"Тэнгу — мастера выживания и общения, одинаково хорошо чувствующие себя как в дикой природе, так и в многолюдных городах. Они накапливают знания, инструменты и компаньонов, пополняя свою коллекцию по мере путешествия.\n\nсвязанное правило","level":0,"traits":["гуманоид","Тэнгу"],"tags":["humanoid","tengu"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{"vo9ge":{"img":"systems/pf2e/icons/features/ancestry/sharp-beak.webp","level":0,"name":"Острый клюв","uuid":"Compendium.pf2e.ancestryfeatures.Item.Sharp Beak","id":"qJD3PJdoSXFrZEwr"}},"rules":[]}},{"id":"hIA3qiUsxvLZXrFP","slug":"fetchling","name":"Фечлинг","cat":"ancestries","type":"ancestry","text":"Некогда люди, а теперь уже нечто обособленное, фечлинги демонстрируют древнее влияние Теневого плана монохромным цветом лица, светящимися глаза и отбрасыванием сверхъестественных теней.\n\nсвязанное правило","level":0,"traits":["Фечлинг","гуманоид"],"tags":["fetchling","humanoid"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["dex"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"flags.system.colorDarkvision","value":true}]}},{"id":"piNLXUrm9iaGqD2i","slug":"hobgoblin","name":"Хобгоблин","cat":"ancestries","type":"ancestry","text":"Выше и сильнее своих гоблинских сородичей, хобгоблины по силе и размеру не уступают людям, и обладают широкими плечами и длинными мощными руками.\n\nсвязанное правило","level":0,"traits":["Хобгоблин","гуманоид"],"tags":["hobgoblin","humanoid"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":["int"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["wis"]}},"items":{},"rules":[]}},{"id":"IiG7DgeLWYrSNXuX","slug":"human","name":"Человек","cat":"ancestries","type":"ancestry","text":"Будучи непредсказуемым и разнообразным, как любой из народов Голариона, люди обладают исключительным стремлением и способностью переносить невзгоды и распространяться. Хотя многие цивилизации процветали до того, как человечество приобрело известность, люди построили одни из величайших и самых ужасных обществ на протяжении всей истории, и сегодня они являются самыми густонаселенными народами в царствах Внутреннего моря.\n\nсвязанное правило","level":0,"traits":["Человек","гуманоид"],"tags":["human","humanoid"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["cha","con","dex","int","str","wis"]},"1":{"value":["str","dex","con","int","wis","cha"]},"2":{"value":[]}},"flaws":{"0":{"value":[]}},"items":{},"rules":[]}},{"id":"x1YinOddgUxwOLqP","slug":"shisk","name":"Шиск","cat":"ancestries","type":"ancestry","text":"Шиски — скрытные горные жители, гуманоиды с костяными перьями, которые прячутся под землей в темных туннелях и пещерах. Их увлеченность коллекционированием и сохранением эзотерических знаний — одна из немногих вещей, которые могут убедить их исследовать внешний мир.\n\nсвязанное правило","level":0,"traits":["гуманоид","Шиск"],"tags":["humanoid","shisk"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["int"]},"1":{"value":[]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":[]}},"items":{},"rules":[]}},{"id":"q6rsqYARyOGXZA8F","slug":"shoony","name":"Шуни","cat":"ancestries","type":"ancestry","text":"Низкорослых гуманоидов, напоминающих коренастых двуногих собак, иногда ошибочно считают слабыми и замкнутыми пацифистами. Однако их упорство, невероятная трудовая этика и изобретательная дипломатия делают шуни далеко не беспомощными.\n\nсвязанное правило","level":0,"traits":["гуманоид","Шуни"],"tags":["humanoid","shoony"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":25,"boosts":{"0":{"value":["cha"]},"1":{"value":["dex"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["con"]}},"items":{"82kag":{"img":"systems/pf2e/icons/features/ancestry/fishseeker-shoony.webp","level":"1","name":"Тупой нос","uuid":"Compendium.pf2e.ancestryfeatures.Item.Blunt Snout","id":"dtNsRAhCRfteA1ev"}},"rules":[]}},{"id":"PgKmsA2aKdbLU6O0","slug":"elf","name":"Эльф","cat":"ancestries","type":"ancestry","text":"Как древний народ, эльфы видели большие перемены и имеют точку зрения, которая может появиться только от наблюдения за ходом истории. Покинув мир в древние времена, они вернулись на измененную землю, и всё ещё борются, чтобы восстановить свои родовые дома, в особенности от ужасных демонов наводнивших части их земель. Для некоторых эльфы это объект изумления, изящные и красивые, с обширными талантами и знаниями. Среди своих же, эльфы уделяют больше внимания личной свободе, чем жизни в соответствии с этими идеалами.\n\nсвязанное правило","level":0,"traits":["Эльф","гуманоид"],"tags":["elf","humanoid"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":6,"speed":30,"boosts":{"0":{"value":["dex"]},"1":{"value":["int"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["con"]}},"items":{},"rules":[]}},{"id":"k3zyr6du4gV0Ftuh","slug":"yaksha","name":"Якша","cat":"ancestries","type":"ancestry","text":"Вдали от сияющих цитаделей и роскошных дворцов, сдержанные якши укрывают сельскую глубинку Тянь Ся от стихийных бедствий и потусторонних напастей. Прославившись твердыми клятвами и мастерством владения природной магией, якши защищают неимущих и охраняют дикую природу, наказывая тех, кто угрожает им, с костедробительной яростью. Легенды о яшках рассказывают об их происхождении как сакральных духов, следивших за безопасностью дорог и жилищ в первобытном мире огромных штормовых лесов и титанических огненных потопов — Первом Мире, мире безграничного потенциала. Во время Великого Забвения , когда боги покинули Первый Мир, многие якши отказались от этого исхода, оставшись выполнять свои обязанности хранителей. Несмотря на внезапную нехватку сакральной силы, оставшиеся якши принесли первозданные обеты, позволяющие им направлять силу из расположенной неподалеку Кузницы Творения в природную магию и превращать участки метафорического Первого Мира в стабильные регионы, дающие убежища обездоленным феям.\n\nсвязанное правило","level":0,"traits":["дух","Якша"],"tags":["spirit","yaksha"],"rarity":"редкий","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["con"]},"1":{"value":["cha"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["int"]}},"items":{},"rules":[]}},{"id":"dnk0Rf7AUmyR5b8z","slug":"yaoguai","name":"Яогай","cat":"ancestries","type":"ancestry","text":"Яогаи обычно начинают как простые животные, растения или предметы, а затем находят способ пробудить в себе разум, превращаясь при этом в странных существ, меняющих форму. Яогаи часто возникают благодаря вливанию энергии окружающей среды в их первоначальную форму, а свою силу они обретают благодаря тренировке врожденной магии. Стараясь не раскрывать свой истинный облик и природу, яогаи одного происхождения или вида иногда образуют анклавы, в которых посвящают свою жизнь совершенствованию своих способностей или гедонистическим занятиям — хотя эти два занятия не являются взаимоисключающими. Яогаи не имеющие прочного сообщества, вынуждены заниматься самосовершенствованием, пока не выйдут за пределы своего происхождения, что позволит им присоединиться к обществу и обрести новый вид свободы.\n\nсвязанное правило","level":0,"traits":["гуманоид","Яогай"],"tags":["humanoid","yaoguai"],"rarity":"редкий","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"hp":8,"speed":25,"boosts":{"0":{"value":["cha"]},"1":{"value":["con"]},"2":{"value":["str","dex","con","int","wis","cha"]}},"flaws":{"0":{"value":["int"]}},"items":{},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Change Shape"}]}}]);
